typedef struct {
    DirectorApp *app;
    gint control_index;
} DirectorCalibrationControlBinding;

typedef struct {
    gdouble tlx, tly;
    gdouble trx, try_;
    gdouble blx, bly;
    gdouble brx, bry;
    gboolean valid;
} DirectorCalibrationQuad;

typedef struct {
    gint state;
    guint timer;
    gint64 frame_after_us;
    gint64 deadline_us;
    DirectorInstance *camera;
    DirectorInstance *a;
    DirectorInstance *b;
    gint pattern_a;
    gint pattern_b;
    GdkPixbuf *black;
    GdkPixbuf *frame_a;
    GdkPixbuf *frame_b;
    gint ax0, ay0, ax1, ay1;
    gint bx0, by0, bx1, by1;
    DirectorCalibrationQuad quad_a;
    DirectorCalibrationQuad quad_b;
    gdouble confidence;
    gboolean discard_next_frame;
    gint overlap_px;
    gint overlap_a_px;
    gint overlap_b_px;
    gboolean horizontal;
} DirectorCalibrationMeasure;

typedef struct {
    gchar *instance_id;
    gint camera_width;
    gint camera_height;
    gint projector_width;
    gint projector_height;
    guint32 *values;
    gsize value_count;
    guint illuminated_pixels;
    guint valid_pixels;
    gdouble mean_confidence;
} DirectorPendingCameraMap;

typedef struct {
    gint state;
    guint timer;
    gint64 frame_after_us;
    gint64 deadline_us;
    DirectorInstance *camera;
    GPtrArray *targets;
    GArray *original_patterns;
    GPtrArray *pending_maps;
    gchar *venue_name;
    guint target_index;
    gint bits_x;
    gint bits_y;
    gint axis;
    gint bit;
    gint camera_width;
    gint camera_height;
    guint16 *gray_x;
    guint16 *gray_y;
    guint8 *range;
    guint8 *valid;
    guint8 *quality;
    guint candidate_pixels;
    GdkPixbuf *black;
    GdkPixbuf *white;
    GdkPixbuf *normal;
    guint captures_done;
    guint captures_total;
    gboolean discard_next_frame;
} DirectorStructuredLightScan;

