static GPtrArray *director_ndi_source_array_copy(const GPtrArray *sources)
{
    GPtrArray *copy = g_ptr_array_new_with_free_func((GDestroyNotify)director_ndi_source_free);
    for(guint i = 0; sources && i < sources->len; i++) {
        const DirectorNdiSource *source = g_ptr_array_index((GPtrArray *)sources, i);
        if(!source)
            continue;
        DirectorNdiSource *item = g_new0(DirectorNdiSource, 1);
        item->name = g_strdup(source->name ? source->name : "");
        item->url = g_strdup(source->url ? source->url : "");
        g_ptr_array_add(copy, item);
    }
    return copy;
}

static void director_ndi_source_record_free(gpointer data)
{
    DirectorNdiSourceRecord *record = data;
    if(!record)
        return;
    g_free(record->name);
    g_free(record->url);
    g_free(record);
}

static gboolean director_ndi_source_cache_prune(gpointer data)
{
    DirectorApp *app = data;
    if(!app || app->shutting_down)
        return G_SOURCE_REMOVE;
    if(!app->ndi_source_cache) {
        app->ndi_source_prune_source_id = 0;
        return G_SOURCE_REMOVE;
    }

    const gint64 now = g_get_monotonic_time();
    gboolean changed = FALSE;
    gboolean have_stale = FALSE;
    gboolean have_classifying = FALSE;
    GHashTableIter iter;
    gpointer value = NULL;
    g_hash_table_iter_init(&iter, app->ndi_source_cache);
    while(g_hash_table_iter_next(&iter, NULL, &value)) {
        DirectorNdiSourceRecord *record = value;
        if(record->online) {
            if(!record->classification_ready) {
                if(record->first_seen_us > 0 &&
                   now - record->first_seen_us >= DIRECTOR_NDI_SOURCE_CLASSIFY_GRACE_US) {
                    record->classification_ready = TRUE;
                    changed = TRUE;
                } else {
                    have_classifying = TRUE;
                }
            }
            continue;
        }
        if(record->missing_since_us <= 0)
            continue;
        if(now - record->missing_since_us >= DIRECTOR_NDI_SOURCE_STALE_EXPIRE_US) {
            g_hash_table_iter_remove(&iter);
            changed = TRUE;
        }
        else {
            have_stale = TRUE;
        }
    }

    if(changed && app->stage_canvas)
        gtk_widget_queue_draw(app->stage_canvas);
    if(!have_stale && !have_classifying) {
        app->ndi_source_prune_source_id = 0;
        return G_SOURCE_REMOVE;
    }
    return G_SOURCE_CONTINUE;
}

static void director_ndi_source_cache_schedule_prune(DirectorApp *app)
{
    if(!app || app->ndi_source_prune_source_id != 0)
        return;
    app->ndi_source_prune_source_id =
        g_timeout_add_seconds(1, director_ndi_source_cache_prune, app);
}

static void director_ndi_source_cache_update(DirectorApp *app,
                                              const GPtrArray *sources,
                                              gint64 observed_us)
{
    if(!app)
        return;
    if(!app->ndi_source_cache)
        app->ndi_source_cache = g_hash_table_new_full(
            g_str_hash, g_str_equal, g_free, director_ndi_source_record_free);

    GHashTableIter iter;
    gpointer value = NULL;
    g_hash_table_iter_init(&iter, app->ndi_source_cache);
    while(g_hash_table_iter_next(&iter, NULL, &value)) {
        DirectorNdiSourceRecord *record = value;
        record->online = FALSE;
        record->matches = 0;
    }

    for(guint i = 0; sources && i < sources->len; i++) {
        const DirectorNdiSource *source = g_ptr_array_index((GPtrArray *)sources, i);
        if(!source || !source->name || !*source->name)
            continue;
        DirectorNdiSourceRecord *record =
            g_hash_table_lookup(app->ndi_source_cache, source->name);
        if(!record) {
            record = g_new0(DirectorNdiSourceRecord, 1);
            record->name = g_strdup(source->name);
            record->first_seen_us = observed_us > 0 ? observed_us : g_get_monotonic_time();
            record->classification_ready = FALSE;
            g_hash_table_insert(app->ndi_source_cache, g_strdup(source->name), record);
        }
        record->online = TRUE;
        record->last_seen_us = observed_us > 0 ? observed_us : g_get_monotonic_time();
        record->missing_since_us = 0;
        record->matches++;
        if(record->matches == 1 || !record->url || !*record->url) {
            g_free(record->url);
            record->url = g_strdup(source->url ? source->url : "");
        }
    }

    gboolean have_stale = FALSE;
    const gint64 now = observed_us > 0 ? observed_us : g_get_monotonic_time();
    g_hash_table_iter_init(&iter, app->ndi_source_cache);
    while(g_hash_table_iter_next(&iter, NULL, &value)) {
        DirectorNdiSourceRecord *record = value;
        if(record->online)
            continue;
        if(record->missing_since_us <= 0)
            record->missing_since_us = now;
        if(record->matches == 0)
            record->matches = 1;
        have_stale = TRUE;
    }
    gboolean have_classifying = FALSE;
    g_hash_table_iter_init(&iter, app->ndi_source_cache);
    while(g_hash_table_iter_next(&iter, NULL, &value)) {
        DirectorNdiSourceRecord *record = value;
        if(record->online && !record->classification_ready) {
            have_classifying = TRUE;
            break;
        }
    }
    if(have_stale || have_classifying)
        director_ndi_source_cache_schedule_prune(app);
}

static gboolean director_ndi_sources_contain_name(const GPtrArray *sources,
                                                   const gchar *name)
{
    if(!name || !*name)
        return FALSE;
    for(guint i = 0; sources && i < sources->len; i++) {
        const DirectorNdiSource *source = g_ptr_array_index((GPtrArray *)sources, i);
        if(source && g_strcmp0(source->name, name) == 0)
            return TRUE;
    }
    return FALSE;
}

static gboolean director_ndi_name_already_added(GHashTable *names, const gchar *name)
{
    if(!name || !*name)
        return TRUE;
    if(g_hash_table_contains(names, name))
        return TRUE;
    g_hash_table_add(names, g_strdup(name));
    return FALSE;
}

static void director_ndi_refresh_combo(DirectorApp *app, const gchar *selected)
{
    if(!app || !app->combo_ndi_source)
        return;

    GtkWidget *entry = gtk_bin_get_child(GTK_BIN(app->combo_ndi_source));
    gint cursor = -1;
    gint selection_start = 0;
    gint selection_end = 0;
    gboolean has_selection = FALSE;
    if(GTK_IS_ENTRY(entry)) {
        cursor = gtk_editable_get_position(GTK_EDITABLE(entry));
        has_selection = gtk_editable_get_selection_bounds(GTK_EDITABLE(entry),
                                                           &selection_start,
                                                           &selection_end);
    }

    app->ndi_selected_source_online =
        director_ndi_sources_contain_name(app->ndi_sources, selected);
    GHashTable *names = g_hash_table_new_full(g_str_hash, g_str_equal, g_free, NULL);

    app->ndi_syncing = TRUE;
    gtk_combo_box_text_remove_all(GTK_COMBO_BOX_TEXT(app->combo_ndi_source));

    if(selected && *selected && !app->ndi_selected_source_online) {
        gtk_combo_box_text_append_text(GTK_COMBO_BOX_TEXT(app->combo_ndi_source), selected);
        g_hash_table_add(names, g_strdup(selected));
    }

    for(guint i = 0; app->ndi_sources && i < app->ndi_sources->len; i++) {
        DirectorNdiSource *source = g_ptr_array_index(app->ndi_sources, i);
        if(source && !director_ndi_name_already_added(names, source->name))
            gtk_combo_box_text_append_text(GTK_COMBO_BOX_TEXT(app->combo_ndi_source), source->name);
    }
    director_ndi_source_set_text(app, selected);
    if(GTK_IS_ENTRY(entry)) {
        if(has_selection)
            gtk_editable_select_region(GTK_EDITABLE(entry), selection_start, selection_end);
        else if(cursor >= 0)
            gtk_editable_set_position(GTK_EDITABLE(entry), cursor);
    }
    app->ndi_syncing = FALSE;
    g_hash_table_destroy(names);
}

static const gchar *director_ndi_discovery_state_name(DirectorNdiDiscoveryState state)
{
    switch(state) {
        case DIRECTOR_NDI_DISCOVERY_STARTING: return "starting";
        case DIRECTOR_NDI_DISCOVERY_WATCHING: return "watching";
        case DIRECTOR_NDI_DISCOVERY_UNAVAILABLE: return "unavailable";
        case DIRECTOR_NDI_DISCOVERY_ERROR: return "error";
        default: return "stopped";
    }
}

static void director_ndi_update_discovery_status(DirectorApp *app)
{
    if(!app || !app->ndi_runtime_label)
        return;

    const gchar *selected = director_ndi_source_text(app);
    app->ndi_selected_source_online =
        director_ndi_sources_contain_name(app->ndi_sources, selected);

    gchar *status = NULL;
    if(!app->ndi_discovery_state_valid) {
        status = g_strdup("NDI discovery starting…");
    }
    else {
        switch(app->ndi_discovery_state) {
            case DIRECTOR_NDI_DISCOVERY_STARTING:
                status = g_strdup(app->ndi_refresh_pending ?
                                  "Refreshing NDI sources…" :
                                  "NDI discovery starting…");
                break;
            case DIRECTOR_NDI_DISCOVERY_WATCHING:
                status = g_strdup_printf("NDI %s · watching · %u source%s%s",
                    app->ndi_discovery_version && *app->ndi_discovery_version ?
                        app->ndi_discovery_version : "runtime",
                    app->ndi_sources ? app->ndi_sources->len : 0,
                    app->ndi_sources && app->ndi_sources->len == 1 ? "" : "s",
                    selected && *selected && !app->ndi_selected_source_online ?
                        " · configured source offline" : "");
                break;
            case DIRECTOR_NDI_DISCOVERY_UNAVAILABLE:
                status = g_strdup("NDI runtime unavailable · retrying");
                break;
            case DIRECTOR_NDI_DISCOVERY_ERROR:
                status = g_strdup_printf("NDI discovery error · retrying%s%s",
                    app->ndi_discovery_error && *app->ndi_discovery_error ? ": " : "",
                    app->ndi_discovery_error && *app->ndi_discovery_error ?
                        app->ndi_discovery_error : "");
                break;
            default:
                status = g_strdup("NDI discovery stopped");
                break;
        }
    }

    gtk_label_set_text(GTK_LABEL(app->ndi_runtime_label), status);

    gchar *tooltip = NULL;
    if(app->ndi_last_update_text && *app->ndi_last_update_text)
        tooltip = g_strdup_printf("%s\nLast NDI discovery update at %s",
                                  status, app->ndi_last_update_text);
    else
        tooltip = g_strdup(status);
    gtk_widget_set_tooltip_text(app->ndi_runtime_label, tooltip);
    g_free(tooltip);
    g_free(status);

    if(app->button_ndi_refresh) {
        const gboolean discovery_allowed = app->selected &&
            app->selected->role != DIRECTOR_ROLE_OUTPUT;
        gtk_button_set_label(GTK_BUTTON(app->button_ndi_refresh),
                             app->ndi_refresh_pending ? "Refreshing…" : "Refresh NDI");
        gtk_widget_set_sensitive(app->button_ndi_refresh,
                                 discovery_allowed && !app->ndi_refresh_pending);
    }
    if(app->stage_wiring_ndi_refresh_button) {
        gtk_button_set_label(GTK_BUTTON(app->stage_wiring_ndi_refresh_button),
                             app->ndi_refresh_pending ? "Refreshing NDI…" : "Refresh NDI");
        gtk_widget_set_sensitive(app->stage_wiring_ndi_refresh_button,
                                 !app->ndi_refresh_pending);
    }

    if(app->ndi_spinner) {
        const gboolean active = app->ndi_refresh_pending ||
            (app->ndi_discovery_state_valid &&
             app->ndi_discovery_state == DIRECTOR_NDI_DISCOVERY_STARTING);
        if(active) {
            gtk_spinner_start(GTK_SPINNER(app->ndi_spinner));
            gtk_widget_show(app->ndi_spinner);
        }
        else {
            gtk_spinner_stop(GTK_SPINNER(app->ndi_spinner));
            gtk_widget_hide(app->ndi_spinner);
        }
    }
}

static gboolean director_ndi_should_log_update(DirectorApp *app,
                                               DirectorNdiDiscoveryState state,
                                               guint source_count,
                                               const gchar *error)
{
    if(!app->ndi_logged_state_valid)
        return TRUE;

    if(state == DIRECTOR_NDI_DISCOVERY_STARTING)
        return app->ndi_refresh_pending;

    if(state == DIRECTOR_NDI_DISCOVERY_WATCHING)
        return app->ndi_logged_state != state ||
               app->ndi_logged_source_count != source_count;

    return app->ndi_logged_state != state ||
           g_strcmp0(app->ndi_logged_error, error) != 0;
}

static void director_ndi_note_logged_update(DirectorApp *app,
                                            DirectorNdiDiscoveryState state,
                                            guint source_count,
                                            const gchar *error)
{
    app->ndi_logged_state_valid = TRUE;
    app->ndi_logged_state = state;
    app->ndi_logged_source_count = source_count;
    g_free(app->ndi_logged_error);
    app->ndi_logged_error = g_strdup(error ? error : "");
}

static void director_ndi_discovery_update(DirectorNdiDiscovery *discovery,
                                          const DirectorNdiDiscoveryUpdate *update,
                                          gpointer user_data)
{
    DirectorApp *app = user_data;
    if(!app || app->shutting_down || discovery != app->ndi_discovery || !update)
        return;

    gchar *selected = g_strdup(director_ndi_source_text(app));
    if(update->state != DIRECTOR_NDI_DISCOVERY_STARTING) {
        GPtrArray *sources = update->state == DIRECTOR_NDI_DISCOVERY_WATCHING ?
            director_ndi_source_array_copy(update->sources) :
            g_ptr_array_new_with_free_func((GDestroyNotify)director_ndi_source_free);
        if(app->ndi_sources)
            g_ptr_array_free(app->ndi_sources, TRUE);
        app->ndi_sources = sources;
        director_ndi_source_cache_update(app, sources, update->observed_us);
        director_ndi_refresh_combo(app, selected);
    }
    app->ndi_generation = update->generation;
    if(update->state != DIRECTOR_NDI_DISCOVERY_STARTING) {
        app->ndi_last_update_us = update->observed_us;
        GDateTime *now = g_date_time_new_now_local();
        g_free(app->ndi_last_update_text);
        app->ndi_last_update_text = now ? g_date_time_format(now, "%H:%M:%S") : NULL;
        if(now)
            g_date_time_unref(now);
    }
    app->ndi_discovery_state_valid = TRUE;
    app->ndi_discovery_state = update->state;
    g_free(app->ndi_discovery_version);
    app->ndi_discovery_version = g_strdup(update->runtime_version ? update->runtime_version : "");
    g_free(app->ndi_discovery_error);
    app->ndi_discovery_error = g_strdup(update->error ? update->error : "");
    g_free(selected);

    if(update->state != DIRECTOR_NDI_DISCOVERY_STARTING)
        app->ndi_refresh_pending = FALSE;
    director_ndi_update_discovery_status(app);

    const guint source_count = app->ndi_sources ? app->ndi_sources->len : 0;
    if(director_ndi_should_log_update(app, update->state, source_count, update->error)) {
        const gchar *state_name = director_ndi_discovery_state_name(update->state);
        if(update->state == DIRECTOR_NDI_DISCOVERY_WATCHING)
            director_log(app, "NDI discovery %s: %u source%s",
                         state_name, source_count, source_count == 1 ? "" : "s");
        else if(update->error && *update->error)
            director_log(app, "NDI discovery %s: %s", state_name, update->error);
        else
            director_log(app, "NDI discovery %s", state_name);
        director_ndi_note_logged_update(app, update->state, source_count, update->error);
    }

    if(app->stage_mode == DIRECTOR_STAGE_MODE_WIRING) {
        director_stage_wiring_update_canvas_size(app);
        if(app->stage_canvas)
            gtk_widget_queue_draw(app->stage_canvas);
    }
}

static void on_ndi_refresh(GtkButton *button, gpointer data)
{
    (void)button;
    DirectorApp *app = data;
    if(!app || app->ndi_refresh_pending)
        return;

    if(!app->ndi_discovery) {
        app->ndi_discovery = director_ndi_discovery_new(
            director_ndi_discovery_update, app);
        director_ndi_discovery_start(app->ndi_discovery);
    }
    else if(app->ndi_discovery_state_valid &&
            app->ndi_discovery_state == DIRECTOR_NDI_DISCOVERY_STOPPED) {
        director_ndi_discovery_start(app->ndi_discovery);
    }

    app->ndi_refresh_pending = TRUE;
    director_ndi_update_discovery_status(app);
    director_ndi_discovery_request_refresh(app->ndi_discovery);
    director_log(app, "Requested an immediate NDI discovery refresh");
    if(app->stage_canvas)
        gtk_widget_queue_draw(app->stage_canvas);
}

static void on_ndi_source_changed(GtkWidget *widget, gpointer data)
{
    DirectorApp *app = data;
    if(!app || app->syncing || app->ndi_syncing)
        return;
    director_ndi_update_discovery_status(app);
    on_startup_controls_changed(widget, data);
}

static void on_startup_controls_changed(GtkWidget *widget, gpointer data)
{
    (void)widget;
    DirectorApp *app = data;
    if(!app || app->syncing || app->ndi_syncing)
        return;
    director_update_role_sensitivity(app);
    if(app->command_preview)
        gtk_label_set_text(GTK_LABEL(app->command_preview),
                           "Settings changed — click Apply configuration to regenerate the launch command.");
}

static void director_media_changed(DirectorApp *app)
{
    if(!app || !app->selected)
        return;
    app->selected->startup_mode = DIRECTOR_STARTUP_MEDIA;
    gtk_combo_box_set_active(GTK_COMBO_BOX(app->combo_startup_source),
                             DIRECTOR_STARTUP_MEDIA);
    app->show->dirty = TRUE;
    director_refresh_media_bank(app);
    director_update_role_sensitivity(app);
    director_update_command_preview(app);
    director_update_header(app);
}

static void on_media_add(GtkButton *button, gpointer data)
{
    (void)button;
    DirectorApp *app = data;
    DirectorInstance *instance = app ? app->selected : NULL;
    if(!instance || instance->role == DIRECTOR_ROLE_OUTPUT)
        return;

    GtkWidget *dialog = gtk_file_chooser_dialog_new("Add startup video files",
                                                    GTK_WINDOW(app->window),
                                                    GTK_FILE_CHOOSER_ACTION_OPEN,
                                                    "Cancel", GTK_RESPONSE_CANCEL,
                                                    "Add files", GTK_RESPONSE_ACCEPT,
                                                    NULL);
    gtk_file_chooser_set_select_multiple(GTK_FILE_CHOOSER(dialog), TRUE);
    GtkFileFilter *filter = gtk_file_filter_new();
    gtk_file_filter_set_name(filter, "Video files");
    gtk_file_filter_add_mime_type(filter, "video/*");
    gtk_file_filter_add_pattern(filter, "*.avi");
    gtk_file_filter_add_pattern(filter, "*.mov");
    gtk_file_filter_add_pattern(filter, "*.mp4");
    gtk_file_filter_add_pattern(filter, "*.mkv");
    gtk_file_filter_add_pattern(filter, "*.mjpeg");
    gtk_file_chooser_add_filter(GTK_FILE_CHOOSER(dialog), filter);

    if(gtk_dialog_run(GTK_DIALOG(dialog)) == GTK_RESPONSE_ACCEPT) {
        GSList *files = gtk_file_chooser_get_filenames(GTK_FILE_CHOOSER(dialog));
        for(GSList *item = files; item; item = item->next) {
            gchar *filename = item->data;
            if(filename && *filename) {
                gchar *canonical = g_canonicalize_filename(filename, NULL);
                gboolean duplicate = FALSE;
                for(guint i = 0; i < instance->media_files->len; i++) {
                    const gchar *existing = g_ptr_array_index(instance->media_files, i);
                    if(g_strcmp0(existing, canonical) == 0) {
                        duplicate = TRUE;
                        break;
                    }
                }
                if(!duplicate)
                    g_ptr_array_add(instance->media_files, canonical);
                else
                    g_free(canonical);
            }
            g_free(filename);
        }
        g_slist_free(files);
        director_media_changed(app);
    }
    gtk_widget_destroy(dialog);
}

static void on_media_remove(GtkButton *button, gpointer data)
{
    (void)button;
    DirectorApp *app = data;
    DirectorInstance *instance = app ? app->selected : NULL;
    if(!instance || !instance->media_files || instance->media_files->len == 0)
        return;
    GList *selected = gtk_flow_box_get_selected_children(GTK_FLOW_BOX(app->media_flow));
    if(!selected) {
        director_error_dialog(app, "Select a media tile to remove.");
        return;
    }
    gint index = gtk_flow_box_child_get_index(GTK_FLOW_BOX_CHILD(selected->data));
    g_list_free(selected);
    if(index >= 0 && (guint)index < instance->media_files->len) {
        g_ptr_array_remove_index(instance->media_files, (guint)index);
        app->show->dirty = TRUE;
        director_refresh_media_bank(app);
        director_update_command_preview(app);
        director_update_header(app);
    }
}

static void on_media_clear(GtkButton *button, gpointer data)
{
    (void)button;
    DirectorApp *app = data;
    DirectorInstance *instance = app ? app->selected : NULL;
    if(!instance || !instance->media_files)
        return;
    g_ptr_array_set_size(instance->media_files, 0);
    app->show->dirty = TRUE;
    director_refresh_media_bank(app);
    director_update_command_preview(app);
    director_update_header(app);
}

static gint director_selected_media_index(DirectorApp *app)
{
    if(!app || !app->media_flow)
        return -1;
    GList *selected = gtk_flow_box_get_selected_children(GTK_FLOW_BOX(app->media_flow));
    if(!selected)
        return -1;
    gint index = gtk_flow_box_child_get_index(GTK_FLOW_BOX_CHILD(selected->data));
    g_list_free(selected);
    return index;
}

static void director_media_move(DirectorApp *app, gint delta)
{
    DirectorInstance *instance = app ? app->selected : NULL;
    if(!instance || !instance->media_files || instance->media_files->len < 2)
        return;
    const gint index = director_selected_media_index(app);
    const gint target = index + delta;
    if(index < 0 || target < 0 || (guint)target >= instance->media_files->len)
        return;
    gpointer tmp = instance->media_files->pdata[index];
    instance->media_files->pdata[index] = instance->media_files->pdata[target];
    instance->media_files->pdata[target] = tmp;
    app->show->dirty = TRUE;
    director_refresh_media_bank(app);
    GList *children = gtk_container_get_children(GTK_CONTAINER(app->media_flow));
    GtkWidget *child = g_list_nth_data(children, target);
    if(child)
        gtk_flow_box_select_child(GTK_FLOW_BOX(app->media_flow), GTK_FLOW_BOX_CHILD(child));
    g_list_free(children);
    director_update_command_preview(app);
    director_update_header(app);
}

static void on_media_left(GtkButton *button, gpointer data)
{
    (void)button;
    director_media_move((DirectorApp*)data, -1);
}

static void on_media_right(GtkButton *button, gpointer data)
{
    (void)button;
    director_media_move((DirectorApp*)data, 1);
}

static void on_choose_working_directory(GtkButton *button, gpointer data)
{
    (void)button;
    DirectorApp *app = data;
    GtkWidget *dialog = gtk_file_chooser_dialog_new("Select instance working directory",
                                                    GTK_WINDOW(app->window),
                                                    GTK_FILE_CHOOSER_ACTION_SELECT_FOLDER,
                                                    "Cancel", GTK_RESPONSE_CANCEL,
                                                    "Select", GTK_RESPONSE_ACCEPT,
                                                    NULL);
    const gchar *current = gtk_entry_get_text(GTK_ENTRY(app->entry_working_directory));
    if(current && *current)
        gtk_file_chooser_set_filename(GTK_FILE_CHOOSER(dialog), current);
    if(gtk_dialog_run(GTK_DIALOG(dialog)) == GTK_RESPONSE_ACCEPT) {
        gchar *folder = gtk_file_chooser_get_filename(GTK_FILE_CHOOSER(dialog));
        gtk_entry_set_text(GTK_ENTRY(app->entry_working_directory), folder ? folder : "");
        g_free(folder);
    }
    gtk_widget_destroy(dialog);
}

static void replace_owned_string(gchar **target, const gchar *value);

static void director_log(DirectorApp *app, const gchar *format, ...)
{
    if(!app || !app->log_view)
        return;

    va_list ap;
    va_start(ap, format);
    gchar *message = g_strdup_vprintf(format, ap);
    va_end(ap);
    gchar *valid_message = g_utf8_make_valid(message ? message : "", -1);

    GDateTime *now = g_date_time_new_now_local();
    gchar *stamp = g_date_time_format(now, "%H:%M:%S");
    gchar *line = g_strdup_printf("[%s] %s\n", stamp, valid_message);
    gvr_log_view_append(GVR_LOG_VIEW(app->log_view), line);
    g_date_time_unref(now);
    g_free(stamp);
    g_free(line);
    g_free(valid_message);
    g_free(message);
}

static gboolean director_show_contains_instance_pointer(const DirectorShow *show,
                                                        const DirectorInstance *instance)
{
    if(!show || !instance || !show->instances)
        return FALSE;
    for(guint i = 0; i < show->instances->len; i++) {
        if(g_ptr_array_index(show->instances, i) == instance)
            return TRUE;
    }
    return FALSE;
}

static gboolean director_calibration_uses_instance(DirectorApp *app,
                                                    const DirectorInstance *instance)
{
    if(!app || !instance)
        return FALSE;
    DirectorCalibrationMeasure *measure = &app->calibration_measure;
    if(measure->camera == instance || measure->a == instance || measure->b == instance)
        return TRUE;
    DirectorStructuredLightScan *scan = &app->calibration_scan;
    if(scan->camera == instance)
        return TRUE;
    for(guint i = 0; scan->targets && i < scan->targets->len; i++) {
        if(g_ptr_array_index(scan->targets, i) == instance)
            return TRUE;
    }
    return FALSE;
}

static void director_calibration_abort_for_instance(DirectorApp *app,
                                                     DirectorInstance *instance,
                                                     const gchar *reason)
{
    if(!director_calibration_uses_instance(app, instance))
        return;
    gchar *id = g_strdup(instance && instance->id ? instance->id : "engine");
    director_calibration_measure_stop(app, TRUE);
    director_calibration_scan_stop(app, TRUE);
    if(app->calibration_result_label) {
        gchar *text = g_strdup_printf("Calibration cancelled because %s%s%s.",
                                      id, reason && *reason ? " " : "",
                                      reason && *reason ? reason : "is no longer available");
        gtk_label_set_text(GTK_LABEL(app->calibration_result_label), text);
        g_free(text);
    }
    director_log(app, "Calibration cancelled: %s%s%s", id,
                 reason && *reason ? " " : "",
                 reason && *reason ? reason : "is no longer available");
    g_free(id);
    director_overview_previews_sync(app);
}

static gboolean director_main_page_is(DirectorApp *app, gint page)
{
    return app && app->notebook &&
           gtk_notebook_get_current_page(GTK_NOTEBOOK(app->notebook)) == page;
}

static gboolean director_screen_page_is(DirectorApp *app, gint page)
{
    return director_main_page_is(app, DIRECTOR_PAGE_SCREEN) &&
           app->screen_setup_notebook &&
           gtk_notebook_get_current_page(GTK_NOTEBOOK(app->screen_setup_notebook)) == page;
}

