static gchar *director_template_directory(void)
{
    return g_build_filename(g_get_user_config_dir(), "veejay", "director", "templates", NULL);
}

static gchar *director_template_slug(const gchar *name)
{
    GString *slug = g_string_new(NULL);
    gboolean dash = FALSE;
    for(const gchar *p = name ? name : ""; *p; p = g_utf8_next_char(p)) {
        gunichar ch = g_utf8_get_char(p);
        if(ch < 128 && g_ascii_isalnum((gchar)ch)) {
            g_string_append_c(slug, g_ascii_tolower((gchar)ch));
            dash = FALSE;
        }
        else if(ch == '-' || ch == '_' || g_unichar_isspace(ch)) {
            if(slug->len && !dash) {
                g_string_append_c(slug, '-');
                dash = TRUE;
            }
        }
    }
    while(slug->len && slug->str[slug->len - 1] == '-')
        g_string_truncate(slug, slug->len - 1);
    if(!slug->len)
        g_string_assign(slug, "setup");
    return g_string_free(slug, FALSE);
}

static void director_template_clear_display_binding(DirectorInstance *instance)
{
    g_free(instance->display_id);
    instance->display_id = g_strdup("");
    g_free(instance->display_name);
    instance->display_name = g_strdup("");
    g_free(instance->display_connector);
    instance->display_connector = g_strdup("");
    instance->display_index = -1;
    instance->display_x = 0;
    instance->display_y = 0;
    instance->display_width = 0;
    instance->display_height = 0;
    instance->window_x = -1;
    instance->window_y = -1;
    memset(&instance->configured_projection, 0, sizeof(instance->configured_projection));
}

static DirectorShow *director_template_clone_show(const DirectorShow *source,
                                                   const gchar *name,
                                                   GError **error)
{
    DirectorShow *copy = director_show_new(name && *name ? name : source->name);
    copy->launch_reloaded = source->launch_reloaded;
    g_free(copy->reloaded_executable);
    copy->reloaded_executable = g_strdup(source->reloaded_executable ? source->reloaded_executable : "reloaded");
    g_free(copy->reloaded_args);
    copy->reloaded_args = g_strdup(source->reloaded_args ? source->reloaded_args : "-a");

    for(guint i = 0; source->instances && i < source->instances->len; i++) {
        DirectorInstance *original = g_ptr_array_index(source->instances, i);
        if(original->discovered_transient)
            continue;
        DirectorInstance *instance = director_instance_clone_configuration(original, original->id);
        instance->wiring_x = original->wiring_x;
        instance->wiring_y = original->wiring_y;
        instance->wiring_position_explicit = original->wiring_position_explicit;
        instance->stage_x = original->stage_x;
        instance->stage_y = original->stage_y;
        instance->stage_position_explicit = original->stage_position_explicit;
        director_template_clear_display_binding(instance);
        g_ptr_array_set_size(instance->media_files, 0);
        if(instance->startup_mode == DIRECTOR_STARTUP_MEDIA)
            instance->startup_mode = DIRECTOR_STARTUP_BLANK;
        if(instance->split_screen_file && *instance->split_screen_file) {
            gchar *path = g_build_filename(instance->working_directory,
                                           "director-video-wall.cfg", NULL);
            g_free(instance->split_screen_file);
            instance->split_screen_file = path;
        }
        if(!director_show_add_instance(copy, instance, error)) {
            director_instance_free(instance);
            director_show_free(copy);
            return NULL;
        }
    }
    copy->dirty = FALSE;
    return copy;
}

static void on_save_setup_template(GtkButton *button, gpointer data)
{
    (void)button;
    DirectorApp *app = data;
    if(!app || !app->show)
        return;

    GtkWidget *dialog = gtk_dialog_new_with_buttons(
        "Save setup as template",
        GTK_WINDOW(app->window),
        GTK_DIALOG_MODAL | GTK_DIALOG_DESTROY_WITH_PARENT,
        "Cancel", GTK_RESPONSE_CANCEL,
        "Save template", GTK_RESPONSE_ACCEPT,
        NULL);
    gtk_dialog_set_default_response(GTK_DIALOG(dialog), GTK_RESPONSE_ACCEPT);
    GtkWidget *content = gtk_dialog_get_content_area(GTK_DIALOG(dialog));
    gtk_container_set_border_width(GTK_CONTAINER(content), 14);
    gtk_box_set_spacing(GTK_BOX(content), 8);
    GtkWidget *hint = gtk_label_new(
        "Templates keep engines, roles, routes, dimensions, Output Graph mapping and startup options. Venue display identities, projection calibration and startup media files are intentionally left out.");
    gtk_label_set_line_wrap(GTK_LABEL(hint), TRUE);
    gtk_widget_set_halign(hint, GTK_ALIGN_START);
    gtk_style_context_add_class(gtk_widget_get_style_context(hint), "dim-label");
    gtk_box_pack_start(GTK_BOX(content), hint, FALSE, FALSE, 0);
    GtkWidget *entry = gtk_entry_new();
    gtk_entry_set_activates_default(GTK_ENTRY(entry), TRUE);
    gtk_entry_set_text(GTK_ENTRY(entry), app->show->name ? app->show->name : "My setup");
    gtk_entry_set_placeholder_text(GTK_ENTRY(entry), "Template name");
    gtk_box_pack_start(GTK_BOX(content), entry, FALSE, FALSE, 0);
    gtk_widget_show_all(dialog);

    if(gtk_dialog_run(GTK_DIALOG(dialog)) != GTK_RESPONSE_ACCEPT) {
        gtk_widget_destroy(dialog);
        return;
    }

    gchar *name = g_strdup(gtk_entry_get_text(GTK_ENTRY(entry)));
    g_strstrip(name);
    if(!*name) {
        gtk_widget_destroy(dialog);
        g_free(name);
        director_error_dialog(app, "Enter a name for the setup template.");
        return;
    }

    gchar *directory = director_template_directory();
    if(g_mkdir_with_parents(directory, 0700) != 0) {
        gchar *message = g_strdup_printf("Cannot create template directory %s: %s",
                                         directory, g_strerror(errno));
        gtk_widget_destroy(dialog);
        g_free(name);
        g_free(directory);
        director_error_dialog(app, message);
        g_free(message);
        return;
    }
    gchar *slug = director_template_slug(name);
    gchar *filename = g_strconcat(slug, ".vjd", NULL);
    gchar *path = g_build_filename(directory, filename, NULL);

    if(g_file_test(path, G_FILE_TEST_EXISTS)) {
        GtkWidget *confirm = gtk_message_dialog_new(GTK_WINDOW(dialog),
            GTK_DIALOG_MODAL | GTK_DIALOG_DESTROY_WITH_PARENT,
            GTK_MESSAGE_QUESTION, GTK_BUTTONS_NONE,
            "Replace setup template ‘%s’?", name);
        gtk_dialog_add_buttons(GTK_DIALOG(confirm),
                               "Cancel", GTK_RESPONSE_CANCEL,
                               "Replace", GTK_RESPONSE_ACCEPT,
                               NULL);
        const gint response = gtk_dialog_run(GTK_DIALOG(confirm));
        gtk_widget_destroy(confirm);
        if(response != GTK_RESPONSE_ACCEPT) {
            gtk_widget_destroy(dialog);
            g_free(name); g_free(directory); g_free(slug); g_free(filename); g_free(path);
            return;
        }
    }

    GError *error = NULL;
    DirectorShow *template_show = director_template_clone_show(app->show, name, &error);
    gboolean saved = template_show && director_show_save(template_show, path, &error);
    if(template_show)
        director_show_free(template_show);
    gtk_widget_destroy(dialog);
    if(saved)
        director_log(app, "Saved reusable setup template ‘%s’", name);
    else {
        director_error_dialog(app, error ? error->message : "Cannot save setup template");
        g_clear_error(&error);
    }
    g_free(name); g_free(directory); g_free(slug); g_free(filename); g_free(path);
}

static void director_workbench_selected_size(const DirectorWorkbenchChooser *chooser,
                                             gint *width,
                                             gint *height)
{
    gint index = chooser && chooser->size_combo ?
        gtk_combo_box_get_active(GTK_COMBO_BOX(chooser->size_combo)) : -1;
    if(index < 0 || index >= (gint)G_N_ELEMENTS(director_video_sizes))
        index = 7;
    if(width)
        *width = director_video_sizes[index].width;
    if(height)
        *height = director_video_sizes[index].height;
}

static GtkListBoxRow *director_workbench_selected_row(const DirectorWorkbenchChooser *chooser)
{
    return chooser ? gtk_list_box_get_selected_row(GTK_LIST_BOX(chooser->list)) : NULL;
}

static const gchar *director_workbench_selected_template(const DirectorWorkbenchChooser *chooser)
{
    GtkListBoxRow *row = director_workbench_selected_row(chooser);
    return row ? g_object_get_data(G_OBJECT(row), "director-template-path") : NULL;
}

static DirectorPreset director_workbench_selected_preset(const DirectorWorkbenchChooser *chooser)
{
    GtkListBoxRow *row = director_workbench_selected_row(chooser);
    if(!row || g_object_get_data(G_OBJECT(row), "director-template-path"))
        return DIRECTOR_PRESET_COUNT;
    return (DirectorPreset)GPOINTER_TO_INT(
        g_object_get_data(G_OBJECT(row), "director-preset"));
}

static void director_workbench_update_summary(DirectorWorkbenchChooser *chooser)
{
    GtkListBoxRow *row = director_workbench_selected_row(chooser);
    const gchar *template_path = director_workbench_selected_template(chooser);
    const DirectorPreset preset = director_workbench_selected_preset(chooser);
    gint width = 1280;
    gint height = 720;
    director_workbench_selected_size(chooser, &width, &height);

    gtk_widget_set_sensitive(chooser->size_combo, template_path == NULL);
    gtk_widget_set_visible(chooser->wall_options,
                           !template_path && preset == DIRECTOR_PRESET_CUSTOM_WALL);
    gtk_widget_set_visible(chooser->dual_options,
                           !template_path && preset == DIRECTOR_PRESET_DUAL_MAPPED_PROJECTOR);
    gtk_spin_button_set_range(GTK_SPIN_BUTTON(chooser->overlap_spin), 0,
                              MAX(0, width - 1));

    gchar *summary = NULL;
    if(template_path) {
        const gchar *saved = row ? g_object_get_data(G_OBJECT(row), "director-template-summary") : NULL;
        summary = g_strdup(saved ? saved : "Reusable user setup template");
    }
    else if(preset == DIRECTOR_PRESET_MASTER_PREVIEW) {
        summary = g_strdup_printf("2 Program engines · %d×%d each · Master stays live while Preview works ahead",
                                  width, height);
    }
    else if(preset == DIRECTOR_PRESET_PROJECTOR_CALIBRATION) {
        summary = g_strdup_printf("1 blank Output · %d×%d · ready for test patterns, mapping and projection-mesh calibration",
                                  width, height);
    }
    else if(preset == DIRECTOR_PRESET_MAPPED_PROJECTOR) {
        summary = g_strdup_printf("Headless Program → Output · %d×%d · Output owns the physical projector",
                                  width, height);
    }
    else if(preset == DIRECTOR_PRESET_DUAL_MAPPED_PROJECTOR) {
        const gint overlap = gtk_spin_button_get_value_as_int(GTK_SPIN_BUTTON(chooser->overlap_spin));
        summary = g_strdup_printf("Headless Program %d×%d → left + right Outputs · %d px overlap · edge blend preconfigured",
                                  width * 2 - overlap, height, overlap);
    }
    else if(preset == DIRECTOR_PRESET_MASTER_PREVIEW_PROJECTOR) {
        summary = g_strdup_printf("Preview ⇢ Master Program → Output · %d×%d · work-ahead control plus one mapped projector",
                                  width, height);
    }
    else if(preset == DIRECTOR_PRESET_CUSTOM_WALL) {
        const gint columns = gtk_spin_button_get_value_as_int(GTK_SPIN_BUTTON(chooser->wall_columns));
        const gint rows = gtk_spin_button_get_value_as_int(GTK_SPIN_BUTTON(chooser->wall_rows));
        const gint64 canvas_width = (gint64)width * columns;
        const gint64 canvas_height = (gint64)height * rows;
        if(columns * rows < 2)
            summary = g_strdup("A video wall needs at least two screens — increase Columns or Rows.");
        else if(canvas_width > 32768 || canvas_height > 32768)
            summary = g_strdup_printf("%d×%d wall would require a %" G_GINT64_FORMAT "×%" G_GINT64_FORMAT " master canvas — reduce the grid or screen size (32768 px limit)",
                                      columns, rows, canvas_width, canvas_height);
        else
            summary = g_strdup_printf("Native %d×%d video wall · %d screen engines · master canvas %" G_GINT64_FORMAT "×%" G_GINT64_FORMAT " · %d×%d per screen",
                                      columns, rows, columns * rows,
                                      canvas_width, canvas_height, width, height);
    }
    else if(preset == DIRECTOR_PRESET_WALL_2X1 ||
            preset == DIRECTOR_PRESET_WALL_1X2 ||
            preset == DIRECTOR_PRESET_WALL_2X2) {
        const gint columns = preset == DIRECTOR_PRESET_WALL_1X2 ? 1 : 2;
        const gint rows = preset == DIRECTOR_PRESET_WALL_2X1 ? 1 : 2;
        summary = g_strdup_printf("Native %d×%d video wall · master canvas %d×%d · %d screen engines · %d×%d per screen",
                                  columns, rows, width * columns, height * rows,
                                  columns * rows, width, height);
    }
    else {
        summary = g_strdup_printf("1 Standalone VeeJay · %d×%d · self-contained playback on one screen",
                                  width, height);
    }
    gtk_label_set_text(GTK_LABEL(chooser->summary), summary);
    g_free(summary);
}

