static void director_activate(GtkApplication *application, gpointer data)
{
    DirectorApp *app = data;
    if(app->window) {
        gtk_window_present(GTK_WINDOW(app->window));
        return;
    }
    app->application = application;
    app->shutting_down = FALSE;
    if(!app->log_readers)
        app->log_readers = g_ptr_array_new();
    app->show = director_default_show();
    app->selected_slice = 0;
    director_build_ui(app);
    app->ndi_discovery = director_ndi_discovery_new(director_ndi_discovery_update, app);
    director_ndi_discovery_start(app->ndi_discovery);
    if(!app->suppress_startup_chooser)
        director_choose_workbench(app);
    app->source_preview_stop = FALSE;
    app->source_preview_thread = g_thread_new("director-program-preview",
                                               director_source_preview_worker, app);
    app->overview_preview_stop = FALSE;
    app->overview_preview_thread = g_thread_new("director-engine-previews",
                                                director_overview_preview_worker, app);
    director_select_instance(app, g_ptr_array_index(app->show->instances, 0));
    for(guint i = 0; i < app->show->instances->len; i++)
        director_ensure_client(app, g_ptr_array_index(app->show->instances, i));
    if(!app->suppress_startup_chooser)
        director_discovery_start(app);
    director_refresh_all_ui(app);
    director_log(app, "VeeJay Director started");
}

static void director_open(GApplication *application,
                          GFile **files,
                          gint n_files,
                          const gchar *hint,
                          gpointer data)
{
    (void)hint;
    DirectorApp *app = data;
    app->suppress_startup_chooser = TRUE;
    director_activate(GTK_APPLICATION(application), app);
    app->suppress_startup_chooser = FALSE;
    if(n_files <= 0)
        return;
    if(!director_confirm_show_replacement(app))
        return;
    gchar *path = g_file_get_path(files[0]);
    if(path) {
        director_load_show_path(app, path);
        g_free(path);
    }
    director_discovery_start(app);
}

static void director_shutdown(GApplication *application, gpointer data)
{
    (void)application;
    DirectorApp *app = data;
    app->shutting_down = TRUE;
    director_stage_clear_wire_drag(app);
    app->stage_ndi_node_dragging = FALSE;
    g_clear_pointer(&app->stage_ndi_drag_key, g_free);
    g_clear_pointer(&app->stage_wire_ndi_hover_key, g_free);
    g_clear_pointer(&app->stage_pending_ndi_sender_id, g_free);
    g_clear_pointer(&app->stage_pending_ndi_target_id, g_free);
    director_eidolon_close_all_views(app);
    director_discovery_stop(app);
    if(app->ndi_discovery) {
        director_ndi_discovery_free(app->ndi_discovery);
        app->ndi_discovery = NULL;
    }
    if(app->ndi_source_prune_source_id) {
        g_source_remove(app->ndi_source_prune_source_id);
        app->ndi_source_prune_source_id = 0;
    }
    if(app->ndi_source_cache) {
        g_hash_table_destroy(app->ndi_source_cache);
        app->ndi_source_cache = NULL;
    }
    if(app->ndi_sources) {
        g_ptr_array_free(app->ndi_sources, TRUE);
        app->ndi_sources = NULL;
    }
    g_clear_pointer(&app->ndi_last_update_text, g_free);
    g_clear_pointer(&app->ndi_discovery_version, g_free);
    g_clear_pointer(&app->ndi_discovery_error, g_free);
    g_clear_pointer(&app->ndi_logged_error, g_free);
    director_ndi_shutdown();
    if(app->live_ui_idle) {
        g_source_remove(app->live_ui_idle);
        app->live_ui_idle = 0;
    }
    director_calibration_measure_stop(app, FALSE);
    director_calibration_scan_stop(app, FALSE);
    director_source_preview_stop(app);
    director_overview_preview_stop(app);
    director_cancel_log_readers(app);
    if(app->start_all_timer)
        g_source_remove(app->start_all_timer);
    if(app->reloaded_process && app->reloaded_running)
        g_subprocess_send_signal(app->reloaded_process, SIGTERM);
    if(app->reloaded_force_stop_timer) {
        g_source_remove(app->reloaded_force_stop_timer);
        app->reloaded_force_stop_timer = 0;
    }
    if(app->reloaded_process) {
        g_subprocess_force_exit(app->reloaded_process);
        g_clear_object(&app->reloaded_process);
    }
    if(app->show) {
        for(guint i = 0; i < app->show->instances->len; i++) {
            DirectorInstance *instance = g_ptr_array_index(app->show->instances, i);
            if(instance->eidolon_running && instance->eidolon_process) {
                g_subprocess_send_signal(instance->eidolon_process, SIGUSR1);
                director_eidolon_write(app, instance, "quit");
                g_subprocess_force_exit(instance->eidolon_process);
            }
            if(instance->reloaded_process)
                g_subprocess_force_exit(instance->reloaded_process);
            director_stop_client(instance);
            if(instance->process_running && instance->process)
                g_subprocess_force_exit(instance->process);
        }
    }
}

int main(int argc, char **argv)
{
    DirectorApp app;
    memset(&app, 0, sizeof(app));
    g_mutex_init(&app.source_preview_lock);
    g_cond_init(&app.source_preview_cond);
    g_mutex_init(&app.overview_preview_lock);
    g_cond_init(&app.overview_preview_cond);
    app.overview_preview_targets = g_ptr_array_new_with_free_func(director_overview_target_free);
    app.overview_preview_frames = g_hash_table_new_full(g_str_hash, g_str_equal, g_free,
                                                        director_overview_frame_free);
    app.discovery_records = g_hash_table_new_full(g_str_hash, g_str_equal, g_free,
                                                   director_discovery_record_free);
    GtkApplication *application = gtk_application_new(DIRECTOR_APP_ID,
                                                       G_APPLICATION_HANDLES_OPEN);
    g_signal_connect(application, "activate", G_CALLBACK(director_activate), &app);
    g_signal_connect(application, "open", G_CALLBACK(director_open), &app);
    g_signal_connect(application, "shutdown", G_CALLBACK(director_shutdown), &app);
    gint status = g_application_run(G_APPLICATION(application), argc, argv);
    if(app.show)
        director_show_free(app.show);
    if(app.log_readers)
        g_ptr_array_free(app.log_readers, TRUE);
    if(app.reloaded_process)
        g_object_unref(app.reloaded_process);
    if(app.overview_preview_targets)
        g_ptr_array_free(app.overview_preview_targets, TRUE);
    if(app.overview_preview_frames)
        g_hash_table_destroy(app.overview_preview_frames);
    if(app.discovery_records)
        g_hash_table_destroy(app.discovery_records);
    if(app.stage_ndi_positions)
        g_hash_table_destroy(app.stage_ndi_positions);
    g_free(app.stage_ndi_drag_key);
    g_free(app.stage_pending_ndi_sender_id);
    g_free(app.stage_pending_ndi_target_id);
    if(app.eidolon_window_views)
        g_ptr_array_free(app.eidolon_window_views, TRUE);
    if(app.calibration_devices)
        g_ptr_array_free(app.calibration_devices, TRUE);
    g_free(app.calibration_selected_device_id);
    g_free(app.calibration_selected_device_path);
    g_free(app.calibration_selected_device_name);
    director_calibration_measure_release_frames(&app.calibration_measure);
    director_calibration_scan_stop(&app, FALSE);
    g_mutex_clear(&app.source_preview_lock);
    g_cond_clear(&app.source_preview_cond);
    g_mutex_clear(&app.overview_preview_lock);
    g_cond_clear(&app.overview_preview_cond);
    g_object_unref(application);
    return status;
}
